<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import {PenLine,Plus,FolderOpen,Check,Package,FileCheck,ShieldCheck,X,LoaderCircle} from 'lucide-vue-next';
import {invoke} from '../bridge';
import {useDesktop} from '../useDesktop';
import {trapModalFocus} from '../modalFocus';
import type {CreatorProject,CreatorMetadata,CreatorResult} from '../../types';
const d=useDesktop();const projects=ref<CreatorProject[]>([]),readOnly=ref(false),selected=ref(''),runtime=ref(''),working=ref(''),error=ref(''),result=ref<CreatorResult|null>(null),details=ref<CreatorResult|null>(null),editor=ref(false),dialog=ref<HTMLElement|null>(null),refreshPins=ref(false);
const templates=[['preset','整套玩法预设'],['worldbook','世界书'],['character','角色卡'],['theme','主题'],['scenario','剧本'],['plugin-ui','界面插件'],['plugin-backend','Python 插件'],['plugin-dice','骰盘插件'],['plugin-campaign','玩法面板插件']];
const labels:Record<string,string>={preset:'玩法预设',worldbook:'世界书',character:'角色卡',theme:'主题',scenario:'剧本',plugin:'插件'};
const messages:Record<string,string>={unsafe_path:'目录、链接或输出位置需要检查。',project_missing:'作品目录不存在，请检查磁盘或重新打开。',project_entry_ambiguous:'请选择包含一个主清单的作品目录。',project_too_large:'作品超过文件数量或体积限制。',output_exists:'目标已存在或在源作品内部，请选择新目录 / 文件名。',output_format:'输出格式与作品类型不匹配。',source_changed:'作品已在其他编辑器修改，请刷新后重新确认。',metadata_invalid:'作品信息字段无效。',contract_invalid:'作品合同未通过，请检查下面的字段位置和源文件。',authors_required:'预设及每个组件需要真实作者署名。',license_required:'预设及每个组件需要明确再分发许可。',publication_blocked:'发布前检查未通过，请在文件夹中检查组件。',sensitive_file:'作品含凭据、数据库或其他私人文件，请先移除再打包。',credential_detected:'作品中检测到密钥形状，请移除后再打包。',permission_denied:'没有文件访问权限，请检查所选目录。',unsupported_operation:'此作品不支持该操作。'};
const project=computed(()=>projects.value.find(p=>p.id===selected.value));
const runtimes=computed(()=>d.state.value.instances.filter(i=>!!i.commit));
const usable=computed(()=>runtimes.value.find(i=>i.id===runtime.value)?.status!=='busy'&&!!runtime.value);
const form=ref({kind:'preset',identity:'my-adventure',name:'我的冒险'}),metadata=ref<CreatorMetadata|null>(null),authors=ref(''),tags=ref('');
const dirty=computed(()=>!!metadata.value&&!!details.value?.metadata&&JSON.stringify({...metadata.value,authors:authors.value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean),tags:tags.value.split(/[、,，\n]/).map(s=>s.trim()).filter(Boolean)})!==JSON.stringify(details.value.metadata));
let reverting=false;let epoch=0,disposed=false,releaseFocus:(()=>void)|undefined;
async function load(){try{const value=await invoke('creatorProjects');if(!disposed){projects.value=value.projects;readOnly.value=value.readOnly;error.value=value.error||'';if(!runtime.value)runtime.value=runtimes.value[0]?.id||'';}}catch(e:any){error.value=e.message;}}
async function operate(label:string,action:()=>Promise<any>){if(working.value)return;const token=++epoch;working.value=label;error.value='';try{const response=await action();if(disposed||token!==epoch||response.cancelled)return;if(response.result){result.value=response.result;if(response.result.ok&&response.result.metadata){details.value=response.result;metadata.value=structuredClone(response.result.metadata);authors.value=metadata.value!.authors.join('\n');tags.value=metadata.value!.tags.join('、');}if(!response.result.ok)error.value=messages[response.result.code||'']||'操作未完成，原作品保留。';}if(response.project){await load();selected.value=response.project.id;}return response;}catch(e:any){if(token===epoch)error.value=e.message;}finally{if(token===epoch)working.value='';}}
function inspect(){if(dirty.value&&!confirm('刷新将重新读取源文件，放弃尚未保存的作品信息。'))return;if(!selected.value||!runtime.value)return;void operate('读取作品',()=>invoke('creatorOperate',{projectId:selected.value,instanceId:runtime.value,operation:'inspect'}));}
watch(runtimes,values=>{if(!runtime.value)runtime.value=values[0]?.id||'';});
watch([selected,runtime],(_next,previous)=>{if(reverting){reverting=false;return;}if(working.value)return;if(dirty.value&&!confirm('作品信息尚未保存，切换将放弃界面中的修改。源文件不变。')){reverting=true;selected.value=previous[0];runtime.value=previous[1];return;}details.value=null;metadata.value=null;result.value=null;refreshPins.value=false;if(!working.value)inspect();});
function request(operation:string,extra:Record<string,any>={}){if(!project.value||!usable.value||operation!=='metadata'&&dirty.value)return;void operate(operation==='package'?'生成版本包':operation==='publication'?'发布前检查':operation==='metadata'?'保存作品信息':operation==='lock'?'更新内容锁':'校验作品',()=>invoke('creatorOperate',{instanceId:runtime.value,projectId:project.value!.id,operation,revision:details.value?.revision,...extra}));}
function save(){if(!metadata.value)return;request('metadata',{metadata:{name:metadata.value.name,version:metadata.value.version,description:metadata.value.description,authors:authors.value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean),license:metadata.value.license,tags:tags.value.split(/[、,，\n]/).map(s=>s.trim()).filter(Boolean)}});}
async function create(){const response=await operate('创建作品',()=>invoke('creatorCreate',{instanceId:runtime.value,...form.value}));if(response?.result?.ok)close();}
async function open(){await operate('打开目录',()=>invoke('creatorOpen',{instanceId:runtime.value}));}
async function showCreate(){if(editor.value)return;editor.value=true;await nextTick();if(dialog.value)releaseFocus=trapModalFocus(dialog.value,()=>{if(!working.value)close();});}
function close(){releaseFocus?.();releaseFocus=undefined;editor.value=false;}
async function forget(){if(!project.value)return;const response=await operate('移除目录记录',()=>invoke('creatorForget',{projectId:project.value!.id}));if(response&&!response.cancelled){selected.value='';await load();}}
onMounted(load);onUnmounted(()=>{disposed=true;epoch++;releaseFocus?.();});
</script>
<template><section class="panel creator-workspace"><div class="panel-title"><div><span class="eyebrow">AUTHOR WORKSPACE</span><h2><PenLine :size="21"/>创作与发布</h2></div><div class="row"><button class="secondary" :disabled="!usable||!!working||readOnly" @click="open"><FolderOpen :size="16"/>打开已有目录</button><button class="primary" :disabled="!usable||!!working||readOnly" @click="showCreate"><Plus :size="16"/>创建作品</button></div></div><p class="help-text">模板、校验与版本包使用公共作者合同，不执行作品的 Python / JavaScript，也不调用 AI。草稿放在独立目录；先准备一间酒馆，借用它的本机运行环境。</p><div class="form form-grid"><label>创作运行环境<select v-model="runtime" aria-label="创作运行环境" :disabled="!!working"><option value="">选择已安装酒馆</option><option v-for="i in runtimes" :key="i.id" :value="i.id">{{i.name}} · {{d.statusLabel[i.status]}}</option></select></label><label>本机作品<select v-model="selected" aria-label="本机作品" :disabled="!!working"><option value="">选择已登记作品</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}} · {{labels[p.kind]}}</option></select></label></div>
 <p v-if="dirty" class="help-text" role="status">作品信息尚未保存。先保存，再校验、打包或发布前检查。</p><p v-if="working" class="help-text" role="status"><LoaderCircle class="spin" :size="16"/>{{working}}…进度可在任务中心查看。</p><p v-if="error" class="warning" role="alert">{{error}}</p><p v-if="result?.positions?.length" class="help-text">需要检查：{{result.positions.join('、')}}</p>
 <div v-if="!projects.length" class="connection-empty"><PenLine :size="25"/><p>从一份模板开始。目录、内容锁与输出都由你明确选择。</p></div>
 <template v-if="project"><div class="panel-title"><code class="storage-path">{{project.directory}}</code><button class="text-button" :disabled="!!working||!usable" @click="operate('打开文件夹',()=>invoke('creatorFolder',{projectId:project!.id,instanceId:runtime}))">打开文件夹编辑</button></div><p class="help-text">在编辑器修改正文与组件；返回后刷新作品。预设的每个组件需单独确认署名和许可，修改组件后明确更新内容锁。旧房间和已生成版本包保留。</p><div v-if="metadata" class="form creator-metadata"><div class="form-grid"><label>稳定 ID<input :value="metadata.id" readonly/></label><label>作品版本<input v-model="metadata.version" maxlength="32" :disabled="!!working" placeholder="1.0.0"/></label><label>作品名称<input v-model="metadata.name" maxlength="80" :disabled="!!working"/></label><label>再分发许可<input v-model="metadata.license" maxlength="80" :disabled="!!working" placeholder="填写你有权声明的许可"/></label></div><label>作品说明<textarea v-model="metadata.description" maxlength="2000" rows="2" :disabled="!!working"/></label><div class="form-grid"><label>作者署名（每行一位）<textarea v-model="authors" rows="2" :disabled="!!working"/></label><label v-if="project.kind!=='plugin'">标签<input v-model="tags" :disabled="!!working" placeholder="用顿号分隔"/></label></div><button class="secondary" :disabled="!!working||!usable||readOnly" @click="save">保存作品信息</button></div><div class="row"><button class="text-button" :disabled="!!working||!usable" @click="inspect">刷新作品</button><button class="secondary" :disabled="!!working||!details||!usable||dirty" @click="request('validate')"><Check :size="16"/>校验作品</button><button v-if="project.kind==='preset'" class="secondary" :disabled="!!working||!details||!usable||dirty" @click="request('lock',{refreshPlugins:refreshPins})"><ShieldCheck :size="16"/>更新草稿内容锁</button><button class="secondary" :disabled="!!working||!details||!usable||dirty" @click="request('package')"><Package :size="16"/>生成新版本包</button><button class="secondary" :disabled="!!working||!details||!usable||dirty" @click="request('publication')"><FileCheck :size="16"/>发布前检查</button><button class="text-button" :disabled="!!working||readOnly" @click="forget">移除目录记录</button></div><label v-if="project.kind==='preset'" class="checkbox"><input v-model="refreshPins" type="checkbox" :disabled="!!working"/>更新内容锁时，也明确刷新已声明模块的本机版本</label><div v-if="result?.ok" class="creator-result" role="status"><p v-if="result.valid">作品合同校验通过。代码审计、版权与试玩仍需独立确认。</p><template v-if="result.publication_ready!==undefined"><p>{{result.publication_ready?'发布前合同与许可声明检查通过。尚未上传或上架。':'发布前检查需要处理以下事项：'}}</p><p v-for="issue in result.issues||[]" :key="issue" class="warning">{{messages[issue]||'请检查源作品'}}</p><code v-if="result.expected_tag">建议不可变标签：{{result.expected_tag}}</code></template><template v-if="result.archive_sha256"><p>新的版本包已保存到原生选择的位置。可能含主持秘密，分享前审阅；没有上传。</p><code class="content-hash">SHA256 · {{result.archive_sha256}}</code></template><code v-if="result.package_hash" class="content-hash">内容锁 · {{result.package_hash}}</code></div></template>
 <p class="help-text">Python 信任、社区目录审核、版权许可与版本包 SHA256 是独立事项。此处不授予模块执行权限，不自动发布到 GitHub。</p>
</section><Teleport to="body"><div v-if="editor" class="overlay"><section ref="dialog" class="dialog" role="dialog" aria-modal="true" aria-label="创建作者作品"><button class="dialog-close" aria-label="关闭创作弹窗" :disabled="!!working" @click="close"><X :size="20"/></button><span class="eyebrow">START A WORLD</span><h2>创建你的作品</h2><form class="form" @submit.prevent="create"><label>作品类型<select v-model="form.kind" aria-label="作品类型" :disabled="!!working"><option v-for="item in templates" :key="item[0]" :value="item[0]">{{item[1]}}</option></select></label><label>作品 ID<input v-model="form.identity" required pattern="[a-z][a-z0-9-]{2,47}" maxlength="48" :disabled="!!working"/></label><label>作品名称<input v-model="form.name" required maxlength="80" :disabled="!!working"/></label><p class="help-text">接下来选择父文件夹，将创建以 ID 命名的新目录。模板的署名与许可留空，填写真实资料后再发布；不会覆盖已有作品。</p><p v-if="error" class="warning" role="alert">{{error}}</p><button class="primary" :disabled="!!working">{{working?'创建中…':'选择位置并创建'}}</button></form></section></div></Teleport></template>
